/* Edit this file to extend the bank. The first answer passed to mc is correct;
   app.js shuffles choices before displaying them. No dependencies or build step. */
(() => {
  const topics = [
    ['foundations', 'Requirements & architecture', 'Functional vs non-functional requirements, architecture, scope, and trade-offs', 'Your requirements reference table; Days 1, 5, 6, 9 and project prompts'],
    ['networking', 'Web requests & delivery', 'DNS, HTTPS, proxies, storage, and CDNs', 'Day 2 — Web Request Lifecycle'],
    ['data', 'Databases & data modeling', 'Relationships, indexes, constraints, and ACID', 'Day 3 — Databases and Data Modeling'],
    ['api', 'API design', 'Resources, status codes, pagination, and contracts', 'Days 5, 6, 10 — API and data design'],
    ['scaling', 'Scaling & capacity', 'Bottlenecks, load balancing, replicas, and queues', 'Days 4, 6 — Scaling and Capacity'],
    ['reliability', 'Reliability & recovery', 'Safe retries, outbox, backups, and failures', 'Days 1, 4, 8 — Reliability'],
    ['caching', 'Caching & consistency', 'Freshness, invalidation, replicas, and outages', 'Days 4, 8, 11 — Caching'],
    ['realtime', 'Real-time systems', 'WebSockets, events, reconnects, and collaboration', 'Days 1, 7, 10 — Real-time Collaboration'],
    ['concurrency', 'Concurrent editing', 'OCC, versions, conflicts, and merging', 'Day 1 study guide; Day 5 — Task App Interview'],
    ['security', 'Authentication & access', 'Permissions, signed URLs, secrets, and validation', 'Days 2, 6, 10, 14 — Access and Secrets'],
    ['state', 'Frontend architecture & state', 'State ownership, drafts, URL state, and caches', 'Day 10 — Frontend System Design, Sessions 1 and 2'],
    ['rendering', 'Rendering & data fetching', 'CSR, SSR, SSG, ISR, hydration, and streaming', 'Day 11 — Rendering, Fetching, and Caching'],
    ['performance', 'Performance & accessibility', 'Loading, rendering, measurements, and keyboard use', 'Day 12 — Frontend Performance and Product Behavior'],
    ['debugging', 'Debugging & race conditions', 'Evidence, debounce, outdated work, and AI review', 'Day 13 — AI-Assisted Debugging'],
    ['delivery', 'Testing & deployment', 'Contracts, meaningful tests, releases, and rollback', 'Day 14 — Codebase, Testing, Review, and Deployment'],
    ["react", "React", "State, Effects, identity, reuse, and rendering performance", "React official documentation · reviewed October 26, 2026"],
    ["nextjs", "Next.js", "App Router boundaries, data access, caching, and server security", "Next.js official documentation · reviewed October 26, 2026"],
    ["nodejs", "Node.js & JavaScript", "Event loop, promises, workers, streams, and failure handling", "Node.js and MDN documentation · reviewed October 26, 2026"]
  ].map(([id, name, description, source]) => ({ id, name, description, source }));
  const questions = [];
  let topic;
  const section = id => { topic = id; };
  const add = q => questions.push({ id: `${topic}-${questions.filter(q => q.topic === topic).length + 1}`, topic, ...q });
  const mc = (prompt, answer, distractors, explanation, sourceUrl) => add({ type: 'choice', prompt, answer, choices: [answer, ...distractors], explanation, ...(sourceUrl ? { sourceUrl } : {}) });
  const blank = (prompt, answers, explanation, sourceUrl) => add({ type: 'blank', prompt, answers, explanation, ...(sourceUrl ? { sourceUrl } : {}) });

  section('foundations');
  mc('Before designing a collaborative task app, what should you clarify first?', 'Core user actions, expected scale, and what is out of scope', ["Choose the cloud provider before discussing the product", "Define a service for every entity before estimating traffic", "Copy a large company architecture without checking its workload"], 'Scope and scale drive the architecture. Choose technology after understanding the requirements.');
  mc('Which is a non-functional requirement for the task app?', 'Confirmed changes should normally reach healthy connected clients within one second', ["Users can create a project", "Owners can invite members", "Members can comment on a task"], 'Non-functional requirements describe quality or constraints. Creating projects and comments describes functionality.');
  mc('For a small PERC launch with a peak of 10–20 requests per second, what is a reasonable starting point?', 'A small API, PostgreSQL, and media storage', ["A separate database shard per customer from launch", "Active-active multi-region writes for every record", "A separate independently deployed service for each API endpoint"], 'Start with components justified by the workload. Add infrastructure when measurements or product requirements warrant it.');
  mc('When asked for high-level components, which answer is most useful?', 'Web client, API, durable database, and real-time delivery service, each with a responsibility', ["A list of frameworks with no explanation of responsibilities", "A detailed class diagram before explaining the request flow", "A deployment topology without describing the data flow"], 'Architecture explains responsibilities and boundaries. Frameworks are implementation choices.');
  mc('A URL shortener has far more redirects than link creations. What should guide the design?', 'Optimize the redirect read path and define link-expiration behavior', ["Optimize creation latency alone because writes are always the bottleneck", "Synchronously finish all analytics aggregation before redirecting", "Assume redirect and creation traffic have identical requirements"], 'The access pattern is read-heavy. Redirect latency and availability matter, while expiration must remain correct enough for the requirements.');
  blank('A measurable quality target should specify a latency _____, such as p95, rather than only an average.', ['percentile'], 'A percentile shows the latency experienced by a portion of requests. An average can hide slow requests.');
  blank('A benefit gained in exchange for a cost or limitation is a _____.', ['trade-off', 'tradeoff', 'trade off'], 'Explain both the benefit and the cost of a decision, then connect the choice to the requirements.');
  blank('An initial backend with clear internal modules but one deployable application is a modular _____.', ['monolith'], 'A modular monolith can preserve boundaries without the deployment and network complexity of many services.');

  // Focused practice based on your functional / non-functional / architecture table.
  mc("“Users can upload and share files.” Which stage does this statement belong to?", "Functional requirements", ["Non-functional requirements", "High-level architecture", "Detailed implementation"], "Functional requirements answer “What can users do?” Uploading and sharing are user capabilities. Durable storage is a quality requirement; object storage is a component choice.");
  mc("“Files must remain durable, and confirmed updates should reach healthy connected users within one second.” Which stage is this?", "Non-functional requirements", ["Functional requirements", "High-level architecture", "Detailed API endpoint design"], "Non-functional requirements answer “How well must it work?” Durability and a delivery-time target describe quality. They do not add a user action or choose a delivery component.");
  mc("“Use a backend API, a metadata database, object storage, and SSE for live notifications.” Which stage is this?", "High-level architecture", ["Functional requirements", "Non-functional requirements", "A measurable performance target"], "High-level architecture answers “What components support that?” These components explain how capabilities and quality targets can be supported. Naming SSE does not itself specify a one-second target.");
  mc("Which statement belongs under functional requirements for a file-sharing service?", "Owners can invite collaborators and revoke a shared link", ["A confirmed upload must survive an application restart", "Share-link creation should meet a defined p95 latency target", "A backend API checks links using a metadata database"], "Inviting collaborators and revoking links are capabilities: what users can do. Surviving a restart and meeting a latency target describe how well it works; the backend and database describe architecture.");
  mc("Which statement belongs under non-functional requirements for a task board?", "For healthy connected clients, p95 commit-to-event delivery should be under one second", ["Members can add comments to tasks", "The design contains an API and a WebSocket service", "Tasks have an assignee that members can change"], "The p95 target measures how well live delivery works. Comments and assignment are functional capabilities. API and WebSocket service are architectural components. The target is not a guarantee during a network outage.");
  mc("Which answer describes high-level architecture rather than a user capability or a quality target?", "A web client sends writes to an API; the database stores metadata, and object storage holds file contents", ["Users can download files they own", "Acknowledged writes must survive an ordinary application restart", "At the agreed load, p95 download-start latency should meet the target"], "Architecture names components, their responsibilities, and how they connect. Downloading is a capability; durability and latency are quality requirements. Start with those requirements before choosing components.");
  mc("A user says, “I need to see teammates’ updates within one second.” Does this require SSE specifically?", "No. It states a quality target; SSE, WebSocket, or another suitable approach is an architecture decision", ["Yes. A one-second target is the definition of SSE", "No. Any statement about timing is a functional user action", "Yes. Writing a non-functional requirement automatically selects its protocol"], "The requirement describes how quickly updates should be visible. SSE is one possible server-to-client delivery mechanism; WebSocket is another option. Choose and measure an approach against the target.");
  mc("You wrote “Use PostgreSQL” under non-functional requirements. What is the clearest correction in this exercise?", "Move PostgreSQL to architecture and state the needed integrity or durability guarantee as a requirement", ["Keep it there because any database name is a quality attribute", "Move it to functional requirements because users perform SQL queries", "Delete all data-quality requirements once a database is chosen"], "PostgreSQL is an implementation choice for the database component. State the required behavior separately, such as preserving acknowledged writes. In a real project a mandated technology can also be an explicit constraint, but its name is not a durability guarantee.");
  mc("Which mapping correctly separates three statements about the same file-sharing system?", "Upload/share → functional; durable storage → non-functional; object storage/database/backend/SSE → architecture", ["Upload/share → architecture; durable storage → functional; object storage/database/backend/SSE → non-functional", "Upload/share → non-functional; durable storage → architecture; object storage/database/backend/SSE → functional", "All three statements are architecture because they describe the same product"], "One feature can be discussed at all three levels. First identify the user capability, then its quality targets, then the components that support them. Related statements do not belong to the same stage just because they concern the same feature.");
  mc("A file-sharing app must enforce permissions. Which classification is most useful?", "“Owners can change permissions” is a capability; “unauthorized users must not access files” is a security constraint; server-side access checks describe the design", ["Every sentence containing “permissions” must be classified as architecture", "Every security-related sentence is functional, regardless of its wording", "Hiding a Share button is both the complete requirement and sufficient authorization architecture"], "Classify the statement, not a single keyword. Managing permissions is a user capability. Preventing unauthorized access is a security constraint. Backend authorization describes how the system enforces it; frontend button visibility is not sufficient.");
  mc("Which revision makes the non-functional requirement “The app should be fast” more useful?", "Define an operation, expected load, measurement boundary, and latency percentile target", ["Replace it with “Use SSE” and remove any timing target", "Replace it with “Users can upload files” and call that a latency measurement", "List a backend and a database without a measurable target"], "“Fast” is a vague quality goal. A target such as p95 event delivery measured from commit to reception under an agreed load can be evaluated. SSE is a mechanism; uploading is a capability; components alone are architecture.");
  mc("Which sequence most clearly connects the three stages in an interview?", "Clarify upload/share actions, define durability and update-delay targets, then explain storage, database, API, and event delivery", ["Select SSE and a database before asking which user actions are needed", "Treat a component list as a substitute for user capabilities and quality targets", "List upload/share actions and assume that reliability is guaranteed without discussing the design"], "Requirements explain what to support and how well. Architecture explains which components support those needs and why. The discussion can iterate, but each design decision should connect back to a requirement.");
  blank("The stage that answers “What can users do?” is _____ requirements.", ["functional", "functional requirements"], "Functional requirements describe user capabilities, such as uploading and sharing files. Non-functional requirements describe qualities; architecture describes supporting components.");
  blank("The stage that answers “How well must it work?” is _____ requirements.", ["non-functional", "nonfunctional", "non functional", "non-functional requirements", "nonfunctional requirements", "non functional requirements"], "Non-functional requirements describe quality targets or constraints, such as durable storage and bounded update delay. They do not mean “features the system does not support.”");
  blank("The stage that answers “What components support that?” is _____ architecture.", ["high-level", "high level", "highlevel", "high-level architecture", "high level architecture"], "High-level architecture names components and responsibilities, such as an API, database, object storage, and event delivery. It supports the previously stated capabilities and quality targets.");
  blank("“Users can share a file” describes a _____ requirement; “updates should arrive within one second” describes a quality target.", ["functional", "functional requirement"], "Sharing is an action a user can perform. The timing statement is non-functional because it describes how well update delivery should work. SSE or WebSocket would be a delivery-design choice.");
  blank("“An acknowledged file upload should survive an ordinary application restart” is a _____ requirement.", ["non-functional", "nonfunctional", "non functional", "non-functional requirement", "nonfunctional requirement", "non functional requirement"], "This states a durability expectation: how well the system must preserve confirmed work. Uploading is the functional capability; durable storage and commit handling belong to the supporting design.");
  blank("A diagram connecting the client, backend, metadata database, object storage, and SSE describes the high-level _____.", ["architecture", "system architecture"], "The diagram shows the components that support the system. It does not replace the user-action list or the measurable quality targets that explain why those components are needed.");

  section('networking');
  mc('What does DNS do when a browser opens a website?', 'Resolves a domain name to addressing information such as an IP address', ["Establishes the encrypted connection to the application", "Distributes HTTP requests across healthy backend instances", "Translates HTML into the rendered page"], 'DNS resolves names. Establishing connections, securing traffic, and rendering happen in other parts of the flow.');
  mc('For HTTPS over TCP, what is the role of TLS?', 'Encrypt and authenticate the connection', ["Provides the resource and method semantics of the request", "Resolves the hostname to the correct IP address", "Makes the business operation safe to retry"], 'TLS secures the connection. This question specifically concerns HTTPS over TCP; HTTP/3 uses QUIC instead.');
  mc('Where should large public audio files normally live in the Musetto design?', 'Object storage, delivered through a CDN', ["In PostgreSQL rows served only through the main API for every download", "Only in the CDN cache, with no durable origin", "In the API instances’ local disks with no shared storage"], 'Object storage retains the files; a CDN caches and delivers them closer to users. Metadata can remain in PostgreSQL.');
  mc('What can a reverse proxy do?', 'Route public requests to internal services and terminate TLS', ["Make related business writes atomic across a database transaction", "Guarantee that every task update reaches every browser exactly once", "Make internal services safe without any access controls"], 'A reverse proxy can route, load-balance, and apply limits. Business rules and data integrity remain application and database responsibilities.');
  mc('How do latency and throughput differ?', 'Latency is time per operation; throughput is work completed per unit of time', ["Latency counts operations per second; throughput measures seconds per operation", "Low latency always means the system can handle more concurrent traffic", "Increasing throughput always lowers every request’s latency"], 'A service can have high throughput while individual requests are slow. Measure both for the workload.');
  blank('When a CDN already has a usable copy of an asset, the request is a cache _____.', ['hit'], 'On a cache miss, the CDN generally needs to fetch from an upstream origin before it can serve and cache the asset.');
  blank('The reliable, ordered byte-stream transport used by HTTP/1.1 and HTTP/2 is _____.', ['TCP', 'Transmission Control Protocol'], 'TCP transports bytes. HTTP defines request and response semantics, and TLS provides transport security for HTTPS over TCP.');
  blank('A Content Delivery Network is commonly abbreviated as _____.', ['CDN'], 'CDN edge locations can reduce user-to-content distance and origin traffic for cacheable assets.');

  section('data');
  mc('Why is PostgreSQL a reasonable fit for PERC purchases?', 'Relations, constraints, and transactions support ownership and credit rules', ["Foreign keys automatically optimize every join and lookup", "Transactions automatically prevent every concurrency anomaly", "Database commits also atomically deliver external emails"], 'PostgreSQL can enforce relational integrity and transactional updates. Correct concurrency and external effects still require deliberate design.');
  mc('How should loops and their audio tracks be modeled when each track belongs to one loop?', 'A loop table and a track table with a loop foreign key', ["Store all track IDs in an unconstrained text field on the loop", "Use the track title as the only link to its parent loop", "Create a many-to-many table because each loop has many tracks"], 'This is a one-to-many relationship. Each track references its parent loop.');
  mc('How do you model a loop that can belong to several genres, each containing many loops?', 'A junction table with loop and genre foreign keys and a unique pair', ["Store a single genre ID on each loop and overwrite it for new genres", "Maintain unrelated ID arrays on both entities without consistency rules", "Store a comma-separated genre name list and rely on client validation"], 'The junction table represents many-to-many membership and can prevent duplicate relationships with a composite unique constraint.');
  mc('What is the difference between a foreign key and an index?', 'A foreign key enforces references; an index can speed matching queries', ["A foreign key always creates a suitable index on the referencing column", "An index enforces that every referenced parent exists", "Adding indexes to every column has no write cost"], 'Choose indexes based on access patterns. In PostgreSQL, a foreign key does not automatically create an index on the referencing columns.');
  mc('One user has one credit and submits two different purchases concurrently. What is needed?', 'Concurrency-safe balance updates, such as suitable row locking inside transactions', ["Use two transactions that both check the original balance without locking", "Check the displayed balance only before sending each request", "Rely only on different idempotency keys to prevent overspending"], 'Atomicity alone does not prevent two operations from using the same stale balance. Serialize or conditionally guard the spend.');
  blank('The ACID property that makes related updates succeed together or roll back together is _____.', ['atomicity'], 'Deducting a credit and recording ownership should be part of the same transaction.');
  blank('The ACID property that means committed changes survive a restart is _____.', ['durability'], 'Durability concerns committed data. Availability and replication are separate concerns.');
  blank('The ACID property that controls how concurrent transactions interact is _____.', ['isolation'], 'Isolation levels and locking affect which concurrent effects are visible and which anomalies are possible.');

  section('api');
  mc('Which request best represents creating a task in a project?', 'POST /projects/42/tasks', ["GET /projects/42/tasks with a request body that creates the task", "PATCH /projects/42 to replace the whole project when adding a task", "PUT /tasks to append a new task without an agreed resource ID"], 'POST to a collection can create a resource. The server must also authenticate, authorize, and validate the request.');
  mc('An authenticated member tries an owner-only action. Which response fits?', '403 Forbidden', ["401 Unauthorized", "404 Not Found as the only permitted access-control response", "200 OK with an error recorded only in server logs"], '403 expresses insufficient permission for an authenticated user. 401 indicates missing or invalid authentication.');
  mc('A task update has an outdated expectedVersion. Which response fits the study design?', '409 Conflict with the current task state', ["200 OK after silently accepting the stale overwrite", "201 Created after creating a second copy of the task", "503 Service Unavailable because all conflicts are server outages"], 'A conflict response lets the client compare the draft with current server data and resolve the stale write.');
  mc('Where should the loop ID and genre filter go in a resource-oriented API?', 'Loop ID in the path; genre filter in query parameters', ["Put both values in a GET body and depend on caches understanding it", "Create a different endpoint name for every possible genre value", "Send the user identity from the browser as the sole authorization proof"], 'For example, GET /loops/42 selects one resource, while GET /loops?genre=jazz filters a collection.');
  mc('What helps paginate a frequently changing task list without shifting offset boundaries?', 'Cursor pagination with a stable sort and a unique tie-breaker', ["Offset pagination with no defined ordering", "Sort only by a non-unique timestamp without a tie-breaker", "Reuse old array positions without refetching while records are inserted"], 'A cursor based on a stable ordered key reduces movement problems. Snapshot consistency can be added if the product requires it.');
  blank('The HTTP status code commonly returned when a resource is successfully created is _____.', ['201', '201 Created'], 'A creation response can include the resource and its location.');
  blank('The HTTP status code for missing or invalid authentication is _____.', ['401', '401 Unauthorized'], 'The conventional reason phrase is Unauthorized, though the distinction to remember is authentication versus permission.');
  blank('For PERC’s predictable resources and a few clients, the study recommends starting with _____ instead of GraphQL.', ['REST'], 'REST is a simple starting point here. GraphQL may be useful when clients need different nested data shapes; system size alone does not decide.');

  section('scaling');
  mc('API CPU is near 95%, while PostgreSQL is healthy. What should you investigate scaling first?', 'The application-server workload', ["Shard the database first even though it is not saturated", "Increase the media-storage quota as the direct CPU fix", "Add read replicas without checking whether database reads are slow"], 'Scale the measured bottleneck. Adding database capacity does not directly fix saturated application CPU.');
  mc('What is horizontal scaling?', 'Adding application instances behind a load balancer', ["Increase CPU and RAM on the existing application server", "Add a larger connection pool to the same saturated instance", "Add more indexes while leaving application capacity unchanged"], 'Horizontal scaling adds instances; vertical scaling increases resources on an existing instance.');
  mc('Why keep API instances stateless?', 'Any healthy instance can handle a request using shared authoritative state', ["Durable user sessions can exist only on the instance that first handled login", "Every request must create a new user identity", "All application state must be removed from the database"], 'Avoid depending on one process’s memory for durable user state. Shared session infrastructure or suitable tokens can support authentication.');
  mc('What does a read replica primarily help with?', 'Distributing database reads, with possible replication lag', ["Distributing primary write traffic automatically across all replicas", "Guaranteeing fresh reads immediately after every primary commit", "Replacing the need for backups and restore testing"], 'Read replicas copy data from a primary. They can be stale and do not automatically distribute writes.');
  mc('A purchase triggers slow waveform generation. What is a reasonable approach?', 'Queue waveform work and process it with workers after the purchase is committed', ["Wait for every waveform and email before confirming the purchase", "Report purchase success before persisting ownership", "Move the credit-balance decision to an eventually consistent browser cache"], 'Move slow secondary work off the request path. Persist the critical purchase outcome before reporting success.');
  blank('Increasing CPU or RAM on a single server is _____ scaling.', ['vertical'], 'Vertical scaling is often simple but has a hardware ceiling and does not by itself remove a single point of failure.');
  blank('A component that distributes requests across healthy application instances is a load _____.', ['balancer'], 'Health checks help it avoid instances that cannot serve traffic.');
  blank('If 120,000 requests arrive evenly over 60 seconds, the average request rate is _____ requests per second.', ['2000', '2,000', '2 000'], '120,000 ÷ 60 = 2,000 RPS. Average traffic is only a baseline; provision with peak patterns and headroom in mind.');

  section('reliability');
  mc('A purchase committed, but its response was lost. How should the client retry?', 'Retry the same operation with the same idempotency key', ["Retry with a new idempotency key because the previous request timed out", "Assume a timeout proves the server did not commit", "Repeat the charge and remove duplicates only if the user complains"], 'The outcome is uncertain after a timeout. A stable key lets the server return the previously recorded result.');
  mc('What problem does a transactional outbox address?', 'A database commit succeeds but the process crashes before publishing its event', ["Keeping a stale browser cache fresh without refetching", "Preventing two users from editing the same task version", "Guaranteeing a broker can never deliver duplicate events"], 'Store the business update and an outbox event in one transaction. A relay can publish the event later. Consumers still need duplicate handling.');
  mc('The primary database is unavailable. Should PERC keep accepting credit purchases?', 'Temporarily stop purchases while retaining safe features such as downloaded playback', ["Approve purchases against the last cached balance and reconcile later", "Return success immediately and store ownership only if the database recovers", "Treat a failed database request as proof the user has sufficient credit"], 'Balances and entitlements need authoritative checks. Degrade individual features according to the guarantees they require.');
  mc('Why are backups not enough by themselves?', 'Recovery must be tested so the data can actually be restored within the needed time', ["A read replica automatically protects against accidental logical deletions", "A successful backup job guarantees restoration will meet recovery targets", "Having backups means the application will have no downtime"], 'A backup strategy needs restore verification and recovery objectives. Replication does not replace protection against deletion or corruption.');
  mc('A worker may receive the same event twice. How should it protect external effects?', 'Use a stable event ID and an idempotent processing strategy', ["Assume an acknowledged queue message can never be delivered again", "Use a new event ID on every retry so duplicate processing is easier", "Run the effect first and assume recording it can never fail afterward"], 'At-least-once delivery can repeat work. Record or deduplicate effects, and use downstream idempotency support where available.');
  blank('A unique key used to make retries of one purchase safe is an _____ key.', ['idempotency', 'idempotent'], 'The server must enforce key uniqueness in the appropriate user/operation scope and store the result with the business change.');
  blank('Before confirming a durable task write, the database transaction should _____.', ['commit'], 'Sending a success response before commit risks acknowledging a change that later fails.');
  blank('Keeping core functionality usable when a secondary service fails is graceful _____.', ['degradation'], 'For example, the HTTP task flow can remain usable while real-time notifications are temporarily unavailable.');

  section('caching');
  mc('Which data is usually safer to serve stale during an outage?', 'A previously cached public catalog description', ["The final credit balance used to authorize a new purchase", "A previous access decision after the user’s permissions were revoked", "The final purchase price without authoritative verification"], 'Browsing can tolerate some staleness. Financial decisions and access control require stronger freshness guarantees.');
  mc('A user purchases a loop and immediately reads from a lagging replica. What could happen?', 'Ownership may appear missing even though the write committed', ["The committed purchase must have rolled back", "Adding more lagging replicas necessarily restores read-your-writes", "The replica is guaranteed to have the primary’s latest value"], 'Replication lag can break read-your-writes expectations. Route critical post-write reads to the primary or use another suitable consistency strategy.');
  mc('When a task moves from Todo to Done, which cached views may need updating?', 'Both Todo and Done results', ["Only the Done view, because removing from Todo is automatic", "Only the task detail, because list caches always synchronize themselves", "Neither, because a successful mutation automatically updates every cache"], 'The item must leave one filtered result and enter another. Update or invalidate all affected views.');
  mc('Is a browser catalog cache the same as a database replica?', 'No; it stores selected reusable data rather than maintaining a database copy', ["Yes; every cached API response automatically follows the database replication log", "Yes; the browser maintains all database tables by default", "No; a cache is allowed to hold only static files, never API data"], 'A cache holds chosen data under application freshness rules. A database replica follows a database replication mechanism.');
  mc('A user changes a status filter without modifying any task. What should happen?', 'Request or reuse the data for the new filter', ["Invalidate every server cache as if the user had modified a task", "Increment task versions to distinguish the new filtered view", "Keep using the previous query result without changing the cache key"], 'A view change is not a mutation. Cache keys should distinguish different query parameters.');
  blank('A cache entry’s time to live is commonly abbreviated as _____.', ['TTL', 'time to live'], 'TTL bounds how long an entry is considered valid under a policy. It does not guarantee that an open browser updates immediately.');
  blank('Removing or marking cached data stale after its source changes is cache _____.', ['invalidation'], 'Invalidation should follow the affected data paths, including lists and details that share the changed entity.');
  blank('The delay between a primary database update and its appearance on a replica is replication _____.', ['lag'], 'The application must account for lag when a user expects to see a just-completed write.');

  section('realtime');
  mc('Which sequence matches the task-app study design?', 'Validate → commit in PostgreSQL → publish event → update connected clients', ["Broadcast a saved event, then validate and attempt the database commit", "Return success after writing only to the API process’s memory", "Publish first and assume the broker will repair a failed database write"], 'Events describing confirmed changes should follow durable persistence. An outbox can close the commit-to-publication crash gap.');
  mc('Why refetch current task data after reconnecting?', 'The client may have missed events while disconnected', ["A new WebSocket connection automatically replays the full event history", "Transport reconnection alone proves the local cache matches the database", "Reconnecting guarantees that all events arrived exactly once"], 'Unless a replay protocol is implemented, reconnecting restores transport but does not recover missed state.');
  mc('What should a client do with an event whose entity version is older than its cached version?', 'Ignore the stale update', ["Apply it because the last event received must always be the newest", "Decrement the cached version to match the event", "Apply it when its network arrival time is later, regardless of entity version"], 'Version checks prevent out-of-order events from regressing state. A version gap may require refetching.');
  mc('Why might a collaborative text editor use OT or a CRDT?', 'To reconcile concurrent text operations and help clients converge', ["To make last-write-wins preserve all concurrent text edits automatically", "To make authenticated document membership unnecessary", "To avoid any need for operation persistence or recovery"], 'Concurrent text editing needs more than overwriting whole documents. OT and CRDT approaches have different constraints and implementation trade-offs.');
  mc('What is the directionality difference between SSE and WebSocket?', 'SSE streams server-to-client; WebSocket supports messages in both directions', ["SSE supports arbitrary client-to-server messages on the same event stream", "WebSocket provides durable storage and automatic replay by default", "Using SSE prevents the client from sending writes over ordinary HTTP"], 'SSE can work alongside ordinary HTTP writes. WebSocket is useful for persistent bidirectional interaction.');
  blank('A persistent bidirectional browser-server connection can use the _____ protocol.', ['WebSocket', 'WebSockets'], 'The connection transports messages; the application still defines authentication, events, persistence, and recovery.');
  blank('Random variation added to reconnect delays to prevent synchronized retries is called _____.', ['jitter'], 'Use jitter with exponential backoff so many disconnected clients do not all reconnect at the same instant.');
  blank('To detect a repeated real-time event, a client can deduplicate using its event _____.', ['ID', 'identifier', 'eventId'], 'An event ID identifies one event. The entity version serves the different purpose of tracking newer and older entity states.');

  section('concurrency');
  mc('When should Task.version increase in the study design?', 'When an update is accepted and saved', ["As soon as a user starts typing a local draft", "Whenever a task is read by another client", "When the form opens, before any accepted server write"], 'Versions track accepted persisted changes. Starting to edit does not create a new server version.');
  mc('Carlos and Sara both read version 4. Carlos saves version 5. Sara submits expectedVersion 4. What should happen?', 'Reject Sara’s stale write with a conflict', ["Accept it because Sara started editing before Carlos saved", "Silently overwrite Carlos’s already-confirmed changes", "Accept both writes with version 5 and resolve it only in the UI"], 'OCC rejects a stale expected version. The client can then resolve or safely merge and retry against current data.');
  mc('What does a three-way merge compare?', 'The base state, the local draft, and the latest server state', ["Only the local draft and the latest server state, with no shared base", "Three timestamps without comparing the edited fields", "The first three versions ever saved for the task"], 'The base reveals which fields each side changed. Without it, a field difference alone does not tell you who modified it.');
  mc('Both users changed the same task title. What should the stale writer’s client do?', 'Show the competing changes and ask that user to resolve the conflict', ["Always concatenate both titles without asking either user", "Discard the stale writer’s draft and display no conflict", "Undo the accepted write before asking the already-confirmed writer to choose"], 'Conflicting intent should be surfaced. Automatic merging is more appropriate for non-overlapping fields under explicit rules.');
  mc('How should a conditional update check the expected version?', 'Atomically in the database update condition', ["Read the version and then perform an unguarded update in a second step", "Check the version only in browser state before submitting", "Use the client’s current clock time as proof no competing write happened"], 'For example, UPDATE ... WHERE id = ? AND version = ?. If no row matches, handle the stale write instead of overwriting.');
  blank('OCC stands for Optimistic _____ Control.', ['Concurrency'], 'OCC allows work without a long-lived edit lock and checks for interference when the change is saved.');
  blank('After merging onto server version 5, a retry should send expectedVersion = _____.', ['5', 'five'], 'The retry targets the latest version used for the merge. Another concurrent update can still cause a new conflict.');
  blank('Immediately showing a pending status change before server confirmation is an optimistic _____ update.', ['UI', 'user interface'], 'Optimistic UI improves perceived speed. It does not replace OCC or backend validation, and failures need reconciliation.');

  section('security');
  mc('Which statement distinguishes authentication and authorization?', 'Authentication identifies the user; authorization checks what they may access', ["Authentication checks resource permissions; authorization establishes identity", "Hiding a forbidden button is sufficient authorization", "An encrypted connection means every connected user is authorized"], 'The backend must enforce access even when the UI hides forbidden actions.');
  mc('How should PERC provide protected full audio downloads?', 'Authenticate, check entitlement, and issue a short-lived signed URL', ["Trust the local ownership badge without checking the server", "Return a permanent public URL for every full asset", "Treat an unguessable loop ID as proof of purchase"], 'Authorize before issuing access. A signed URL limits delivery access but cannot prevent an authorized person from copying downloaded audio.');
  mc('Where should a database password be stored?', 'In server-side secret configuration', ["In a frontend environment variable that is compiled into the browser bundle", "In a browser configuration file hidden behind an uncommon filename", "In localStorage so the frontend can connect directly to the database"], 'Anything shipped to the browser is inspectable. Naming a value an environment variable does not make a frontend bundle private.');
  mc('A user subscribes to a project’s WebSocket channel. What must the server check?', 'That the authenticated user is allowed to access that project', ["Only that the requested project ID has a valid format", "Only that the client claims membership in its subscription payload", "Only that the connection uses TLS"], 'Encryption protects transport. It does not prove project membership or permission to receive events.');
  mc('A database credential was accidentally published. What is necessary?', 'Rotate the actual credential and verify that the old one no longer works', ["Remove it from the next release while leaving the old password valid", "Remove the visible string from the repository but keep the same credential", "Rename the environment variable without changing the actual credential"], 'An exposed secret may already be copied. Removing its visible text does not revoke its access.');
  blank('Checking access rules for individual database rows is often called Row Level _____ (RLS).', ['Security'], 'RLS can enforce database-level access policies, provided the identity, policies, and server privileges are configured correctly.');
  blank('A temporary media URL cryptographically tied to access conditions is a _____ URL.', ['signed'], 'Keep its lifetime appropriate to the use case. A signed URL is a bearer capability for whoever possesses it while valid.');
  blank('Even if the browser validates a form, the _____ must validate requests again.', ['backend', 'server', 'API'], 'Clients can be modified or bypassed, so the API cannot rely on UI restrictions for data integrity or security.');

  section('state');
  mc('Which is temporary client state on a task board?', 'Whether the edit modal is open', ["The project member’s saved role", "The authoritative persisted task version", "The committed ownership record"], 'Modal visibility is UI state. Tasks and memberships are server state, even though the browser caches a copy.');
  mc('Where should shareable task filters and pagination usually be stored?', 'URL query parameters', ["Only in component memory, even when the view must survive refresh", "In localStorage alone, even when the view must be shareable by URL", "In the task’s persisted version field"], 'URL state survives refresh, can be shared, and works with browser history.');
  mc('A WebSocket update arrives while a user is editing that task. What should the frontend do?', 'Preserve the local draft and indicate that newer server data is available', ["Replace local form values immediately so all state always matches the cache", "Ignore all later server updates until the browser is restarted", "Automatically submit the unfinished draft before receiving more events"], 'The server-state cache and the unsaved draft have different responsibilities. Preserve user work and provide reconciliation.');
  mc('Several components display the same task. How can redundant requests be reduced?', 'Use a shared server-state cache keyed by the task identity', ["Fetch independently in every leaf component with no shared cache key", "Create a separate WebSocket connection for each field component", "Maintain separate authoritative local copies with no synchronization strategy"], 'A shared data layer can deduplicate fetches and coordinate updates, loading, errors, and freshness.');
  mc('What should happen while session validity is still being checked?', 'Show a loading state until authentication is known', ["Show a final permission error before the session check finishes", "Fetch and display private data before authorization is known", "Redirect every user to sign-in without checking a possibly valid session"], 'Unknown authentication state differs from unauthenticated or forbidden. The UI should represent that distinction.');
  blank('A task edit form should usually own its input values, validation, and unsaved _____ locally.', ['draft', 'drafts', 'changes', 'state'], 'Keep form work close to the component responsible for it, then synchronize after a confirmed save.');
  blank('To distinguish cached searches, include the relevant filters in the cache _____.', ['key'], 'For example, project ID, status, assignee, and page can distinguish separate results instead of overwriting each other.');
  blank('For non-sensitive preferences that should survive a browser refresh, a simple browser API is _____.', ['localStorage', 'local storage', 'window.localStorage'], 'Local storage is device/browser-specific and can be cleared. Do not use it as authoritative remote data or a place for passwords.');

  section('rendering');
  mc('PERC has about 100 public pages that change every few months. What is a simple initial rendering strategy?', 'SSG with a rebuild when content is released', ["Uncached server rendering for every visit regardless of freshness needs", "Client-only rendering solely because all public pages need authentication", "ISR with a runtime requirement even when release-time rebuilds meet the need"], 'Static generation is a reasonable fit for small, rarely changing public content. Reconsider when publishing or freshness needs change.');
  mc('What does a one-hour time-based ISR interval mean in the study example?', 'After the interval the cached page becomes eligible for request-triggered regeneration', ["The page rebuilds at each exact hour even if nobody visits", "The server pushes refreshed HTML to all already-open tabs at the interval", "The whole site must be rebuilt on every request after the interval"], 'Time-based ISR is not a strict hourly job. A later request can receive stale content while regeneration happens.');
  mc('Does a Server Component always mean the page renders on every request?', 'No; where a component runs is distinct from when a page is generated', ["Yes; Server Components cannot participate in static generation", "Yes; using a Server Component disables all caching automatically", "No; a Server Component means its code runs only in the browser"], 'Server Components can participate in static or dynamic rendering. Do not equate component boundaries with a single rendering schedule.');
  mc('Can a pure static export regenerate new pages after deployment using ISR?', 'No; runtime regeneration requires a supporting server runtime', ["Yes; a cached HTML file runs its own regeneration job", "Yes; the browser can write the regenerated page back to the static host", "Yes; setting an interval removes the need for any runtime"], 'A static export only serves generated files. New or changed output needs another build and deployment.');
  mc('Recommendations are slow but the track title is ready. What can streaming with a boundary do?', 'Show the ready content first and deliver the slower section later', ["Make the recommendation query itself execute faster automatically", "Remove the dependency when recommendations need the track query’s result", "Guarantee the full page is interactive before any client JavaScript loads"], 'Streaming improves progressive delivery. Truly dependent queries still have an ordering dependency.');
  blank('Generating page HTML at build time is Static Site Generation, abbreviated _____.', ['SSG'], 'Build-time generation avoids rendering the same public content on every visit.');
  blank('Attaching browser behavior to existing server-generated HTML is called _____.', ['hydration'], 'Initial HTML can be visible before client-side event handlers become interactive.');
  blank('If two data requests do not depend on one another, start them in _____ to avoid an unnecessary waterfall.', ['parallel', 'concurrently'], 'If one request needs data from the other, their dependency must still be respected.');

  section('performance');
  mc('Why load audio previews on demand instead of downloading every full track at catalog load?', 'Reduce initial transfer and let people browse sooner', ["Eliminate all playback startup latency after clicking Play", "Make preload measurement unnecessary because less transfer always improves every metric", "Guarantee that no preview data will ever be downloaded"], 'This trades lower initial cost for possible playback startup delay. Measure catalog readiness and playback separately.');
  mc('What does list virtualization reduce?', 'The number of list items rendered in the DOM at once', ["The total records fetched from the server in every implementation", "All database query time regardless of how data is requested", "The need for pagination or filtering in every product"], 'Virtualization renders a visible window of a long list. Pagination and filtering address data-transfer size separately.');
  mc('How can you reduce layout shifts from images?', 'Reserve their space with suitable dimensions or aspect ratios', ["Insert images at their natural size without reserving layout space", "Hide the scrollbar while images load", "Increase the network timeout so the browser waits longer before showing content"], 'Reserving space helps avoid unexpected movement when media loads.');
  mc('After a modal closes, where should focus usually return?', 'To the control that opened it', ["Always to the first link on the page regardless of the opening control", "To an invisible element so focus cannot distract the user", "Leave focus inside the removed dialog"], 'Manage focus on open and close, keep modal interactions keyboard accessible, and provide clear control names.');
  mc('A click feels slow. Which metric is designed to reflect interaction responsiveness?', 'INP', ["CLS", "The count of successful HTTP responses", "The total downloaded audio storage size"], 'Interaction to Next Paint concerns how promptly a page visually responds to interactions. Responsive layout means adapting to screen sizes.');
  blank('LCP stands for Largest Contentful _____.', ['Paint'], 'LCP measures when the largest qualifying visible content element is rendered.');
  blank('CLS stands for Cumulative Layout _____.', ['Shift'], 'CLS concerns unexpected layout movement, not the latency of a network request.');
  blank('Tools such as screen readers are examples of assistive _____.', ['technology', 'technologies'], 'Semantic elements, accessible names, focus management, and keyboard interaction help people use the site with these tools.');

  section('debugging');
  mc('A user says “search is broken.” What should you do first?', 'Clarify the expected result, actual result, and reproduction steps', ["Increase the debounce delay before reproducing the behavior", "Rewrite the backend before inspecting its responses", "Assume the first plausible AI explanation is the root cause"], 'A concrete symptom and reproduction give you a behavior to investigate and later verify.');
  mc('Why can debounced search still display outdated results?', 'An earlier request can finish after a later request', ["Debouncing enforces that responses finish in the order requests started", "A successful status code proves that a response belongs to the current input", "Clearing the debounce timer always cancels an already-started request"], 'Debounce controls when requests start, not when responses finish. Guard the relevance of results.');
  mc('Why invalidate old work on every input change, rather than only when a new request starts?', 'An old response can arrive while the new debounce timer is still waiting', ["A new request ID automatically changes as soon as the user types", "A longer debounce delay guarantees that old responses cannot arrive", "Aborting a browser request guarantees the server stops all related work"], 'The current input can change before a new request starts. Use an input version or equivalent relevance guard immediately.');
  mc('Which state changes need protection from outdated requests?', 'Results, errors, and loading indicators', ["Only successful response data; stale errors can always be shown", "Results and errors, but an old finally handler can always stop loading", "Only the loading flag; older data is harmless if it arrived successfully"], 'An old failure must not replace a current success, and an old finally handler must not stop a newer loading state.');
  mc('Play does nothing, no audio request appears, and a related JavaScript error is logged. Where do you start?', 'Inspect the frontend error and the flow before the request', ["Start by replacing the audio-storage provider without inspecting the exception", "Treat the absent network request as proof that the backend rejected it", "Silently catch the exception and assume playback is fixed"], 'Trace the handler, its data, and the point of failure. An early frontend error can prevent the request from starting.');
  blank('A possible explanation that still needs evidence is a _____.', ['hypothesis'], 'Check a hypothesis against request timing, response data, and actual UI behavior before choosing a fix.');
  blank('Delaying a search request until the user pauses typing is called _____.', ['debouncing', 'debounce'], 'Keep input text responsive while delaying the request. Debouncing alone does not resolve response races.');
  blank('A bug whose outcome depends on the timing of operations is a race _____.', ['condition'], 'Controlled response ordering can reproduce a race reliably instead of depending on an unpredictable network.');

  section('delivery');
  mc('A genre filter shows Jazz but the request only contains search text. What should a review identify?', 'The frontend is not sending the selected genre at the API boundary', ["A backend bug is proven even though the request omitted the parameter", "A successful HTTP status proves the genre filter is implemented", "The dropdown display automatically communicates the selection to the API"], 'Follow the feature from inputs through request parameters, backend filtering, response, and display.');
  mc('What is the strongest assertion for a genre-and-text filtering test?', 'The expected match is included and records failing either filter are excluded', ["The server returned 200, regardless of which records it returned", "The response is an array, even if the expected match is absent", "The dropdown contains a Jazz option, regardless of the API request"], 'A meaningful test verifies the actual behavior and should fail if filtering is broken.');
  mc('What does a mocked frontend API test fail to prove by itself?', 'That the real backend query returns correct database records', ["That the UI can render a simulated API response", "That interacting with the controls can include both filters in a request", "That a simulated error response produces the expected error state"], 'Mocks isolate frontend behavior. Test real backend logic and integration separately where needed.');
  mc('A feature works locally but fails after deployment. What should you check early?', 'Deployed version, production API URL, environment configuration, and observed requests', ["Assume the deployed code and database are identical to development", "Clear every cache before checking the outgoing request or response", "Inspect only the locally running version because the build succeeded there"], 'Verify which code and services are actually running, then trace the failing request and response.');
  mc('A release breaks filtering and no fix is verified. What may restore service?', 'Roll back to a compatible last working version', ["Deploy the first unverified patch because it compiles locally", "Roll back without checking compatibility with the current API or schema", "Keep the broken version live because a passing build proves filtering works"], 'Check compatibility with current APIs and schema before rollback. Then investigate and verify the fix.');
  blank('A quick check of the main behavior immediately after deployment is a _____ test.', ['smoke'], 'A smoke test can confirm that the live release loads and its critical flow works with the production configuration.');
  blank('A test intended to keep a previously fixed bug from returning is a _____ test.', ['regression'], 'For the search race, control the response order and assert that older work cannot replace current results.');
  blank('A test that checks components working together, such as an API and test database, is an _____ test.', ['integration'], 'Unit tests focus on a small unit; end-to-end tests exercise a broader user flow through the app.');

  section('react');
  mc("A React task list and toolbar must always show the same selected task. What is a reasonable state design?", "Keep one selected-task state in their closest suitable common owner and pass values and callbacks down", ["Keep separate selected-task copies and synchronize both with Effects", "Move all application state into every task card", "Read the selected task by querying another component’s DOM"], "One owner avoids contradictory copies. Lift shared state to a suitable common parent; keep unrelated temporary state close to its consumer. Shared state does not automatically require a global store.", "https://react.dev/learn/sharing-state-between-components");
  mc("In one click handler, count is 0 and setCount(count + 1) runs three times. What happens after React processes these updates?", "The next count is 1; three updater functions such as setCount(c => c + 1) would produce 3", ["The next count is always 3 because every setter mutates the local variable immediately", "The three setters create three independent state variables", "React rejects repeated setters in one handler"], "The handler sees one render’s state snapshot. Each expression requests the value 1. Updater functions are applied to the pending state in sequence, so three increments compose correctly.", "https://react.dev/learn/queueing-a-series-of-state-updates");
  mc("A task title is stored inside a React state object. How should an edit normally update it?", "Create a new object with the changed field and pass that object to the setter", ["Mutate task.title and pass the same object reference back", "Modify the DOM text and leave state unchanged", "Mutate the shared object so every previous render’s snapshot changes too"], "Treat state as immutable. Copy every changed level of nested data. Mutating an existing object can break snapshots and React’s identity-based update checks.", "https://react.dev/learn/updating-objects-in-state");
  mc("A sortable task list has editable rows. Which key should identify each row?", "A stable task ID that identifies the same task across reorders", ["The array index even when tasks move between positions", "A new random value generated on every render", "The current title even when users can edit or duplicate it"], "Keys let React match siblings across renders. Stable IDs preserve the intended component identity and local state. Index or changing keys can associate edits with the wrong row or reset them.", "https://react.dev/learn/rendering-lists");
  mc("A React Effect subscribes to project events. What should happen when projectId changes or the component unmounts?", "Clean up the old subscription and synchronize with the current project using the correct dependencies", ["Keep every old subscription active so no event is ever missed", "Use an empty dependency array even though projectId changes", "Open a new connection during every render without cleanup"], "Effects synchronize with external systems. Cleanup releases the previous subscription. Correct dependencies keep it aligned with the current project and prevent duplicate listeners or stale closures.", "https://react.dev/learn/synchronizing-with-effects");
  mc("A filtered task list can be calculated from tasks and status during render. Should it normally be copied into state using an Effect?", "No; derive it during rendering, and only cache the calculation if useful after measurement", ["Yes; all derived values must be stored independently", "Yes; an Effect is the only place filtering can happen", "No; derived values must always be persisted to the backend"], "Avoid redundant state when an existing value can be derived. An Effect adds a synchronization path and extra rendering work. Memoization can help an expensive calculation but is not needed for correctness.", "https://react.dev/learn/you-might-not-need-an-effect");
  mc("Which value is a good candidate for useRef rather than useState?", "A timeout handle that must survive renders but is not itself displayed", ["A counter whose new value must immediately appear on screen", "The selected filter that determines the rendered list", "An error message that the user must see when it changes"], "A ref retains a mutable value across renders without scheduling a render when current changes. Use state for data whose changes should update the UI.", "https://react.dev/reference/react/useRef");
  mc("What does a React Error Boundary mainly provide?", "A fallback for errors thrown while rendering descendants; ordinary event-handler and async failures still need their own handling", ["Automatic handling of every rejected promise in the application", "A replacement for all API validation and retries", "A guarantee that the backend operation rolled back"], "An Error Boundary can isolate a rendering failure. It does not catch every error source, such as an ordinary event-handler failure or arbitrary asynchronous callback error. Handle those explicitly.", "https://react.dev/reference/react/Component#catching-rendering-errors-with-an-error-boundary");
  mc("A teammate proposes wrapping every component in memo to fix a slow board. What is the best response?", "Profile the interaction, identify costly renders, and use appropriate optimizations rather than relying on memo for correctness", ["Memo guarantees that a component will never render again", "Memo prevents all state and context updates automatically", "Adding memo fixes slow database requests before they reach the browser"], "memo can skip some renders when props are unchanged, but state and consumed context can still update a component. Measure first; compiler-enabled projects may already apply memoization automatically.", "https://react.dev/reference/react/memo");
  mc("Two components call the same custom Hook that internally creates useState. Do they automatically share one state instance?", "No; the Hook reuses logic, while each call has its own state unless it connects to a shared owner or external store", ["Yes; a Hook’s name identifies a global singleton state", "Yes; exporting a Hook automatically persists its state for all users", "No; custom Hooks cannot call built-in Hooks"], "Custom Hooks share stateful logic, not automatically the state itself. Shared data needs a shared owner, context, or a suitable external data source.", "https://react.dev/learn/reusing-logic-with-custom-hooks");
  blank("The React Hook that expresses local state transitions using a reducer and dispatch is _____.", ["useReducer", "useReducer()"], "useReducer groups related transition logic. The reducer must be pure and return the next state; it is not a database transaction.", "https://react.dev/reference/react/useReducer");
  blank("The React Hook that reads and subscribes to the nearest matching context provider is _____.", ["useContext", "useContext()"], "Context supplies a value to descendants without passing it through every intermediate component. Provider value changes can rerender consumers; context is not a server-data cache by itself.", "https://react.dev/reference/react/useContext");
  blank("When manually caching an expensive calculation between renders based on dependencies, the React Hook is _____.", ["useMemo", "useMemo()"], "useMemo caches a calculation result as a performance optimization. It is not durable storage or a correctness guarantee, and React Compiler may reduce the need for manual calls.", "https://react.dev/reference/react/useMemo");
  blank("When manually caching a callback’s identity between renders based on dependencies, the React Hook is _____.", ["useCallback", "useCallback()"], "useCallback caches the function identity, not its execution result. Accurate dependencies still matter; it does not automatically fix a stale closure.", "https://react.dev/reference/react/useCallback");
  blank("Hooks such as useState and useEffect should be called at the _____ level of a component or custom Hook, rather than inside conditions or loops.", ["top", "top level", "top-level"], "Stable Hook ordering lets React associate calls with their state. These rules concern Hooks such as useState and useEffect; React’s use API has different documented rules.", "https://react.dev/reference/rules/rules-of-hooks");

  section('nextjs');
  mc("A Next.js App Router product page contains public details and one interactive favorite button. How should you choose the client boundary?", "Keep suitable page content on the server and make the interactive button a small Client Component", ["Mark the root layout use client because one descendant has a click handler", "Send the database client to the browser so the button can write directly", "Make every page a Client Component to avoid thinking about data boundaries"], "Place interactivity where needed instead of pulling the whole layout into the client bundle. Server-rendered content and small interactive regions can be composed together.", "https://nextjs.org/docs/app/getting-started/server-and-client-components");
  mc("What does use client change for a Next.js module?", "It establishes a client boundary, so its imported runtime dependencies must be suitable for the client bundle", ["It makes server-only dependencies safe to send to browsers", "It automatically converts every visually nested Server Component into client code", "It prevents Next.js from producing any initial HTML for that component"], "The boundary follows the module graph. Server Components can be passed as rendered children from a server parent; visual nesting alone does not determine which modules are bundled.", "https://nextjs.org/docs/app/api-reference/directives/use-client");
  mc("Does Client Component mean that no HTML can be rendered for it on the server during the initial page load?", "No; Next.js can prerender its initial HTML, then hydrate it for interactivity", ["Yes; Client Components always produce a completely empty initial HTML response", "Yes; using useState disables all server-generated HTML for the route", "No; it means browser event handlers execute on the database server"], "Client Components can participate in the initial HTML preview. Their JavaScript is needed for hydration and interaction. Component execution boundaries and initial HTML delivery are related but distinct.", "https://nextjs.org/docs/app/getting-started/server-and-client-components");
  mc("A Server Component needs records owned by the same Next.js application. Should it normally call its own public Route Handler over HTTP?", "Prefer calling a server-only data-access function directly, with authorization enforced there", ["Always call the public URL because local server code cannot query data", "Fetch from the browser first so the server can read localStorage", "Put database credentials in the component props and let the client choose"], "A Server Component can access its data source through server code. Calling its own HTTP endpoint adds a round trip and can fail during prerendering when no application server is listening.", "https://nextjs.org/docs/app/guides/backend-for-frontend");
  mc("A Server Action deletes a task. The page already checked the user’s session. What must the action do?", "Validate the input and independently check the caller’s authentication and permission for that task", ["Trust the task ID because the page hid the Delete button", "Skip authorization because use server makes the function private to its page", "Accept the browser’s claimed owner ID as proof of permission"], "A Server Action is a separate server entry point. A page-level check does not authorize every later action. Validate inputs and enforce resource-level permissions inside the server operation.", "https://nextjs.org/docs/app/guides/data-security");
  mc("How should you explain Next.js caching in an interview when the application version and configuration are not yet known?", "State the freshness needs, identify the cache layers, and make the policy explicit for the chosen version and configuration", ["Claim that every server fetch is cached forever in all Next.js versions", "Claim that Server Components always render dynamically and can never cache data", "Use one shared public cache for every response, including private purchases"], "Next.js caching behavior depends on configuration and has changed across versions. Separate request deduplication, reusable server data, rendered output, and browser state instead of assuming one universal default.", "https://nextjs.org/docs/app/getting-started/caching");
  mc("After a Server Action changes a track title, why might server cache revalidation alone be insufficient for another user’s already-open tab?", "The other tab needs a refresh, refetch, or live notification to update its own displayed state", ["Revalidation always broadcasts the new title to every connected browser", "The title must be stored permanently in localStorage instead of the database", "A successful mutation guarantees that all client caches instantly agree"], "Refreshing affected server caches and updating another open browser are separate concerns. The caller may receive updated UI through the mutation flow; other clients still need an update mechanism.", "https://nextjs.org/docs/app/getting-started/mutating-data");
  mc("A server page needs a product and an unrelated list of featured categories. How can it avoid an unnecessary request waterfall?", "Start both independent requests before awaiting their combined results", ["Always await the product before starting any other request", "Put both awaits inside separate sequential useEffect calls on the server", "Assume Promise.all can remove a real dependency between requests"], "Independent requests can overlap. If the second request truly needs data from the first, keep that dependency. Streaming and concurrency help different parts of delivery.", "https://nextjs.org/docs/app/getting-started/fetching-data");
  mc("An external payment provider calls a Next.js webhook Route Handler. What should the handler rely on before accepting the event?", "Validate the provider’s signature using the required request representation and handle duplicate event IDs safely", ["Trust the event because a browser previously displayed a successful checkout", "Accept any body claiming to come from the provider without verification", "Require a hidden frontend button as the only proof of authenticity"], "Webhook endpoints receive external requests. Follow the provider’s signature protocol, including raw-body requirements where applicable, and make repeated delivery safe. A checkout UI is not proof of a trusted event.", "https://nextjs.org/docs/app/guides/backend-for-frontend");
  mc("A Server Component retrieves a user row containing private internal fields. What should it pass to a Client Component?", "Only a minimal, authorized data shape containing fields the browser is allowed to receive", ["The entire row because Server Component origin keeps all passed props secret", "The database connection object so the browser can filter the fields itself", "All server environment variables so the Client Component can authorize locally"], "Server execution does not keep values secret once they cross into client-visible output or props. Return safe DTOs and enforce authorization in the server-only data layer.", "https://nextjs.org/docs/app/guides/data-security");
  blank("In an App Router project using TypeScript, HTTP methods such as GET and POST can be exported from an app/api/tasks/_____ file.", ["route.ts"], "A route.ts file defines a Route Handler using Web Request and Response APIs. A page.tsx file serves a page; it is not the same convention.", "https://nextjs.org/docs/app/api-reference/file-conventions/route");
  blank("In a TypeScript App Router segment, the special file for a loading UI that automatically supplies a Suspense boundary is _____.", ["loading.tsx"], "loading.tsx provides a route-segment fallback while its content is loading. It does not make the underlying query faster, and more local Suspense boundaries can control finer-grained streaming.", "https://nextjs.org/docs/app/api-reference/file-conventions/loading");
  blank("In a TypeScript App Router segment, the Client Component file that defines its error-boundary fallback is _____.", ["error.tsx"], "error.tsx handles errors in the segment’s child tree. The segment’s own layout sits outside that boundary; root-level failures can require global-error.tsx. It is not a replacement for handling expected validation errors.", "https://nextjs.org/docs/app/api-reference/file-conventions/error");
  blank("The Next.js environment-variable prefix that allows direct references to be bundled for the browser is _____.", ["NEXT_PUBLIC_"], "Public-prefixed values are not secrets. Direct references are typically inlined at build time, so deploying the same built bundle with a different environment does not automatically change those values.", "https://nextjs.org/docs/app/guides/environment-variables");
  blank("The directive that marks a React module as a client entry point in the Next.js App Router is _____.", ["use client", "'use client'", "\"use client\""], "Put use client at the top of the entry module when it needs browser state or events. It marks a boundary; you do not need to repeat it in every imported client-side file.", "https://nextjs.org/docs/app/api-reference/directives/use-client");

  section('nodejs');
  mc("How can a Node.js process serve many clients while JavaScript callbacks normally run on one main event-loop thread?", "It uses non-blocking I/O and schedules callbacks as work becomes ready, provided callbacks do not monopolize that thread", ["It creates a new JavaScript thread for every HTTP request by default", "Every callback runs simultaneously on the main thread", "The async keyword moves all JavaScript computation into the operating system"], "I/O concurrency is not the same as parallel JavaScript execution. Short callbacks and asynchronous I/O let the event loop serve other clients while external work is pending.", "https://nodejs.org/learn/asynchronous-work/overview-of-blocking-vs-non-blocking");
  mc("An async HTTP handler performs a large CPU-intensive JavaScript calculation before its first await. What should you expect?", "The calculation still blocks its event-loop thread; consider a worker pool or a background job for suitable CPU work", ["The async keyword automatically runs the calculation on another CPU core", "Adding Promise.resolve around the calculation makes it non-blocking", "Database read replicas automatically remove the JavaScript CPU bottleneck"], "Declaring a function async does not offload synchronous computation. Worker threads can execute CPU-intensive JavaScript in parallel; a pool avoids creating a new worker for each small task.", "https://nodejs.org/api/worker_threads.html");
  mc("Several independent operations have already started and are awaited with Promise.all. What happens if one rejects?", "The combined promise rejects, but the other operations are not automatically cancelled", ["Every operation is automatically rolled back and cancelled", "Promise.all resolves with only the successful values", "The remaining promises stop using resources because their values are no longer awaited"], "Promise.all is fail-fast for its result, not a cancellation or transaction mechanism. Design cancellation and partial side effects explicitly.", "https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Using_promises");
  mc("A dashboard should show each successful widget even if another widget fails. Which promise combinator gives every operation’s outcome?", "Promise.allSettled", ["Promise.all with no rejection handling", "Promise.race, which waits for every outcome", "A synchronous forEach that ignores each returned promise"], "Promise.allSettled waits for fulfillment or rejection of every input. Inspect each status to render partial success. Still bound concurrency when the workload could overwhelm downstream services.", "https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Using_promises");
  mc("You must process writes sequentially and finish them before returning. Why is items.forEach(async item => await save(item)) insufficient?", "forEach does not await those callbacks; use a for...of loop with await for sequential processing", ["forEach always serializes async callbacks automatically", "An async callback converts forEach into Promise.all", "Awaiting forEach waits for all its callback promises"], "forEach ignores the promises returned by its callback. A for...of loop can await each write. For independent parallel work, explicitly collect promises and choose an appropriate concurrency limit.", "https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/forEach");
  mc("A Node.js endpoint must send a large file to a slow client. What is a sensible design?", "Stream chunks and respect downstream backpressure rather than buffering the entire file", ["Read the entire file into memory separately for every client", "Keep writing without checking whether the receiver can keep up", "Assume async functions eliminate all buffering and memory limits"], "Streams can limit memory use when the producer respects consumer speed. Use appropriate stream composition and handle errors; uncontrolled buffering can exhaust memory under concurrent downloads.", "https://nodejs.org/learn/modules/backpressuring-in-streams");
  mc("A request handler stops waiting after a timeout. Does that guarantee the downstream fetch or database operation stopped?", "No; propagate an abort signal or use the operation’s cancellation API where supported, and handle uncertain side effects", ["Yes; rejecting a promise automatically cancels every operation behind it", "Yes; Promise.race always aborts the losing operations", "No; the only solution is to retry immediately without limits"], "A timeout and cancellation are distinct. AbortController signals cancellation to APIs that support it; it does not undo a remote operation that already committed.", "https://nodejs.org/api/globals.html#class-abortcontroller");
  mc("What does const config = { retries: 3 } guarantee in JavaScript?", "The config binding cannot be reassigned, but its object properties can still be mutated", ["Every nested property is deeply immutable", "The object is automatically frozen across all modules", "Any attempt to change config.retries must throw because the binding is const"], "const protects the binding, not the object’s contents. Shared mutable objects still require care; creating a copy or using suitable immutability techniques is a separate decision.", "https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/const");
  mc("Inside an async handler, which pattern catches rejection of loadTask() at that point?", "Use await loadTask() inside try/catch, or explicitly handle the returned promise’s rejection", ["Call loadTask() without await inside try/catch and assume later rejection is caught", "Ignore the promise because HTTP handlers cannot fail asynchronously", "Convert the promise to a string before returning it"], "A surrounding synchronous try/catch does not catch a later rejection from a promise you did not await. Await within the try block or return a properly handled chain, with a clear error-response policy.", "https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/async_function");
  mc("A Node.js HTTP service receives a termination signal during deployment. What is a sensible graceful-shutdown sequence?", "Stop accepting new traffic, drain in-flight work within a deadline, then release resources and exit", ["Immediately terminate every active request regardless of its progress", "Keep accepting traffic forever while closing the database pool", "Register a signal handler and assume requests and WebSockets drain automatically"], "Coordinate readiness and request draining. server.close can stop accepting connections while HTTP work finishes, but upgraded connections and external resources need their own handling. Use a deadline rather than waiting forever.", "https://nodejs.org/api/http.html#serverclosecallback");
  blank("A JavaScript function together with access to the lexical environment where it was created is a _____.", ["closure"], "Closures let callbacks retain access to surrounding variables. They capture bindings; whether a callback observes an older render value or a later mutation depends on how those bindings are created and updated.", "https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Closures");
  blank("The mechanism that schedules ready JavaScript callbacks in Node.js is the event _____.", ["loop"], "The event loop coordinates callback execution. Blocking its thread delays other requests, even when those requests are otherwise independent.", "https://nodejs.org/learn/asynchronous-work/event-loop-timers-and-nexttick");
  blank("When a stream consumer is slower than its producer, controlling the producer to avoid unbounded buffering is called _____.", ["backpressure", "back pressure"], "For manual writes, a false return from writable.write signals that production should pause until drain. Stream composition such as pipeline can coordinate this along with error handling.", "https://nodejs.org/learn/modules/backpressuring-in-streams");
  blank("A JavaScript async function always returns a _____, even if its body returns an ordinary value.", ["Promise", "a Promise"], "The returned value is wrapped in a promise. Awaiting a promise pauses that async function’s continuation; it does not turn CPU-heavy synchronous work into parallel execution.", "https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/async_function");
  blank("The Node.js built-in module for running JavaScript in worker threads is node:_____.", ["worker_threads", "worker threads", "worker-threads"], "worker_threads is useful for suitable CPU-intensive JavaScript work. Ordinary asynchronous I/O is usually better handled by Node’s existing non-blocking I/O mechanisms.", "https://nodejs.org/api/worker_threads.html");

  window.QUIZ_DATA = { version: 1, topics, questions };
})();
